test('invoiceTotals calculates discount based on tier default', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: undefined }],
  }).value;
  const totals = invoiceTotals(invoice);
  // DES-HOUR: 100 * 8500 = 850000 cents (€8500)
  // discount: 850000 * 5 / 100 = 42500 cents (€425)
  assert.equal(totals.subtotal, 850000);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.total, 807500);
});

test('invoiceTotals with multiple lines and tier discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 }, // gets 2.5%
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // explicit 10%
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 8500 = 85000, discount = 85000 * 2.5 / 100 = 2125
  // Line 2: 5 * 9500 = 47500, discount = 47500 * 10 / 100 = 4750
  // Subtotal: 85000 + 47500 = 132500
  // Total discount: 2125 + 4750 = 6875
  // Total: 132500 - 6875 = 125625
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 6875);
  assert.equal(totals.total, 125625);
});

test('createInvoice stores tier discount on line (no explicit discountPercent)', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  // Verify the line has the discount stored as a property
  assert.equal(result.value.lines[0].hasOwnProperty('discountPercent'), true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('issueInvoice preserves tier-applied discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('addLine does not apply tier discount (addLine is for draft modification)', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  // addLine should not apply tier discount when no discountPercent is provided
  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(result.ok, true);
  // The line added by addLine should NOT have tier discount applied
  assert.equal(result.value.lines[1].discountPercent, undefined);
});

