    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount (2.5%) by default', () => {
  const result = createInvoice({
    customerId: 'C-003', // Kite & Co is silver tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0%) by default', () => {
  const result = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery is standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discountPercent overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice explicit 0% discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice handles multiple lines with different tier discounts', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // no explicit discount, gets gold 5%
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 3 }, // explicit 3%
      { sku: 'ICON-SET', qty: 1, discountPercent: 0 }, // explicit 0%
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5); // gold tier default
  assert.equal(result.value.lines[1].discountPercent, 3); // explicit override
  assert.equal(result.value.lines[2].discountPercent, 0); // explicit override
});

test('createInvoice with silver customer and mixed explicit/tier discounts', () => {
  const result = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // gets silver 2.5%
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 5 }, // explicit 5%
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('invoiceTotals calculates discount based on tier default', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: undefined }],
  }).value;
  const totals = invoiceTotals(invoice);
  // DES-HOUR: 100 * 8500 = 850000 cents (€8500)
  // discount: 850000 * 5 / 100 = 42500 cents (€425)
  // DES-HOUR vatRate: 21, VAT = (850000 - 42500) * 21 / 100 = 807500 * 21 / 100 = 169575
  assert.equal(totals.subtotal, 850000);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.vat, 169575);
  assert.equal(totals.total, 850000 - 42500 + 169575);
});

test('invoiceTotals with multiple lines and tier discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 }, // gets 2.5%, vatRate 21
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // explicit 10%, vatRate 21
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 8500 = 85000, discount = 85000 * 2.5 / 100 = 2125, after discount = 82875, VAT = 82875 * 21 / 100 = 17403.75 → 17404
  // Line 2: 5 * 9500 = 47500, discount = 47500 * 10 / 100 = 4750, after discount = 42750, VAT = 42750 * 21 / 100 = 8977.5 → 8978
  // Subtotal: 85000 + 47500 = 132500
  // Total discount: 2125 + 4750 = 6875
  // Total VAT: 17404 + 8978 = 26382
  // Total: 132500 - 6875 + 26382 = 152007
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 6875);
  assert.equal(totals.vat, 26382);
  assert.equal(totals.total, 152007);
});

test('createInvoice stores tier discount on line (no explicit discountPercent)', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  // Verify the line has the discount stored as a property
  assert.equal(result.value.lines[0].hasOwnProperty('discountPercent'), true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('issueInvoice preserves tier-applied discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('addLine does not apply tier discount (addLine is for draft modification)', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  // addLine should not apply tier discount when no discountPercent is provided
  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(result.ok, true);
  // The line added by addLine should NOT have tier discount applied
  assert.equal(result.value.lines[1].discountPercent, undefined);
});

test('lineVAT returns 0 when vatRate is 0', () => {
  const line = { qty: 5, unitPrice: 1000, vatRate: 0 };
  assert.equal(lineVAT(line), 0);
});

test('lineVAT calculates VAT on line amount before discount', () => {
  // Line: 10 * 100 = 1000, no discount, VAT 21% = 1000 * 21 / 100 = 210
  const line = { qty: 10, unitPrice: 100, vatRate: 21 };
  assert.equal(lineVAT(line), 210);
});

test('lineVAT calculates VAT after discount is applied', () => {
  // Line: 10 * 100 = 1000, discount 10% = 100, after discount = 900, VAT 21% = 900 * 21 / 100 = 189
  const line = { qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 21 };
  assert.equal(lineVAT(line), 189);
});

test('lineVAT rounds per line', () => {
  // Line: 100 * 100 = 10000, discount 0%, VAT 9% = 10000 * 9 / 100 = 900
  const line = { qty: 100, unitPrice: 100, vatRate: 9 };
  assert.equal(lineVAT(line), 900);
});

test('lineVAT handles decimal VAT rates', () => {
  // Test with 9% VAT
  const line = { qty: 3, unitPrice: 500, vatRate: 9 };
  // Amount = 1500, VAT = 1500 * 9 / 100 = 135
  assert.equal(lineVAT(line), 135);
});

test('lineVAT clamps result at 0', () => {
  // lineVAT should never go negative
  const line = { qty: 1, unitPrice: 100, vatRate: 0 };
  assert.equal(lineVAT(line) >= 0, true);
});

test('invoiceTotals includes VAT in calculation', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000, discount = 0, VAT = 10000 * 21 / 100 = 2100
  // total = 10000 - 0 + 2100 = 12100
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 2100);
  assert.equal(totals.total, 12100);
});

test('invoiceTotals with multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 100, vatRate: 21 }, // 10000, VAT = 2100
      { qty: 100, unitPrice: 100, vatRate: 9 },  // 10000, VAT = 900
      { qty: 100, unitPrice: 100, vatRate: 0 },  // 10000, VAT = 0
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 3000); // 2100 + 900 + 0
  assert.equal(totals.total, 33000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000, discount = 1000, amount = 9000, VAT = 9000 * 21 / 100 = 1890
  // total = 10000 - 1000 + 1890 = 10890
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals per-line VAT rounding with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 500, vatRate: 9 },  // 1500, VAT = 135
      { qty: 2, unitPrice: 1000, vatRate: 21 }, // 2000, VAT = 420
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 3500);
  assert.equal(totals.vat, 555); // 135 + 420, not (3500 * avg_rate)
  assert.equal(totals.total, 4055);
});

test('invoiceTotals clamped total with high VAT', () => {
  // Even with high VAT, total should not go below 0
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100, discount = 100, amount after discount = 0, VAT = 0
  // total = 100 - 100 + 0 = 0 (clamped)
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('renderInvoiceText shows VAT line when VAT > 0', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = invoiceResult.value;
  const renderResult = require('../src/render.js').renderInvoiceText(invoice);
  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // Should contain VAT line since DES-HOUR has 21% VAT
  assert(text.includes('VAT:'), 'VAT line should be in rendered output');
  assert(text.includes('Total:'), 'Total line should be in rendered output');
});

test('renderInvoiceText does not show VAT line when VAT = 0', () => {
  // Create a manual invoice with no VAT
  const invoice = {
    customerId: 'C-001',
    number: 'INV-2026-0001',
    status: 'issued',
    lines: [
      { sku: 'TEST', name: 'Test Item', qty: 1, unitPrice: 1000, vatRate: 0 }
    ]
  };
  const renderResult = require('../src/render.js').renderInvoiceText(invoice);
  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // Should not contain VAT line since VAT = 0
  assert(!text.includes('VAT:'), 'VAT line should not be in output when VAT = 0');
  assert(text.includes('Total:'), 'Total line should be in rendered output');
});

